-- kairos:no-transaction
-- fk_indexes (WP-12; database-99, 02-database 11.2 and 11.4): every foreign key gets an index on its leading columns, and
-- credit_ledger's invoice key widens to (invoice, reason) with one free grant per user (billing-44, billing-v02).
-- Generated by drizzle-kit, then made CONCURRENTLY IF NOT EXISTS by hand so no write waits on a build and a rerun after a
-- partial run is safe; the runner refuses to record the file while an index it left is invalid. The old invoice index is
-- dropped last, once its replacement exists.
CREATE INDEX CONCURRENTLY IF NOT EXISTS "facts_resume_profile_idx" ON "facts" USING btree ("resume_profile_id") WHERE "facts"."resume_profile_id" is not null;--> statement-breakpoint
CREATE INDEX CONCURRENTLY IF NOT EXISTS "resumes_resume_profile_idx" ON "resumes" USING btree ("resume_profile_id") WHERE "resumes"."resume_profile_id" is not null;--> statement-breakpoint
CREATE INDEX CONCURRENTLY IF NOT EXISTS "matches_job_idx" ON "matches" USING btree ("job_id");--> statement-breakpoint
CREATE INDEX CONCURRENTLY IF NOT EXISTS "applications_job_idx" ON "applications" USING btree ("job_id");--> statement-breakpoint
CREATE INDEX CONCURRENTLY IF NOT EXISTS "applications_match_idx" ON "applications" USING btree ("match_id") WHERE "applications"."match_id" is not null;--> statement-breakpoint
CREATE INDEX CONCURRENTLY IF NOT EXISTS "applications_resume_profile_idx" ON "applications" USING btree ("resume_profile_id") WHERE "applications"."resume_profile_id" is not null;--> statement-breakpoint
CREATE INDEX CONCURRENTLY IF NOT EXISTS "inbound_emails_application_idx" ON "inbound_emails" USING btree ("application_id","received_at") WHERE "inbound_emails"."application_id" is not null;--> statement-breakpoint
CREATE UNIQUE INDEX CONCURRENTLY IF NOT EXISTS "credit_ledger_invoice_reason_uq" ON "credit_ledger" USING btree ("stripe_invoice_id","reason") WHERE "credit_ledger"."stripe_invoice_id" is not null;--> statement-breakpoint
CREATE UNIQUE INDEX CONCURRENTLY IF NOT EXISTS "credit_ledger_one_free_grant_uq" ON "credit_ledger" USING btree ("user_id") WHERE "credit_ledger"."reason" = 'free_grant';--> statement-breakpoint
DROP INDEX CONCURRENTLY IF EXISTS "credit_ledger_invoice_uq";
